function configure({ website_name, url, instruction }) {
  if (
    typeof website_name !== "string" ||
    !website_name.trim() ||
    typeof instruction !== "string" ||
    !instruction.trim()
  ) {
    throw new Error("Enter the webpage name and description instructions");
  }
  if (typeof url !== "string" || !/^https?:\/\/[^\s/?#@]+(?:[/?#][^\s]*)?$/i.test(url)) {
    throw new Error("Enter a public HTTP or HTTPS webpage URL");
  }
  return {
    website_name: website_name.trim(),
    url,
    instruction,
    request: { url, full_page: true, format: "png", save_hashes: true },
  };
}
export default configure;

