function checkImage({ bytes, mime, size }) {
  const signature = [137, 80, 78, 71, 13, 10, 26, 10];
  if (
    mime !== "image/png" ||
    bytes.length !== size ||
    !signature.every((value, index) => bytes[index] === value)
  ) {
    throw new Error("Downloaded screenshot is not the expected PNG");
  }
}
export default async function prepare({ file, digest, size, instruction }, context) {
  if (file.digest !== "sha256:" + digest)
    throw new Error("Screenshot digest does not match URLbox");
  const bytes = await context.artifact.open(file);
  checkImage({ bytes, mime: file.mediaType, size });
  const chunkSize = 12288;
  let base64 = "";
  for (let offset = 0; offset < bytes.length; offset += chunkSize) {
    base64 += btoa(String.fromCharCode(...bytes.subarray(offset, offset + chunkSize)));
  }
  return {
    input: [
      {
        role: "user",
        content: [
          { type: "input_text", text: instruction },
          { type: "input_image", image_url: "data:image/png;base64," + base64, detail: "auto" },
        ],
      },
    ],
  };
}

