function checkDescription(value) {
  if (typeof value !== "string" || !value.trim() || value.length > 4096) {
    throw new Error("The model did not return a complete description");
  }
  return value.trim();
}
export default function check({ response }) {
  if (response?.status !== "completed")
    throw new Error("The model did not complete screenshot analysis");
  const blocks = (response.output ?? [])
    .filter((record) => record.type === "message" && record.role === "assistant")
    .flatMap((record) => record.content ?? []);
  if (blocks.some((block) => block.type === "refusal"))
    throw new Error("The model declined screenshot analysis");
  return {
    description: checkDescription(
      blocks
        .filter((block) => block.type === "output_text" && typeof block.text === "string")
        .map((block) => block.text)
        .join("\n"),
    ),
  };
}
